import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Términos del servicio","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/terms.md","filePath":"es/guide/terms.md","lastUpdated":1793173149000}`),a={name:`es/guide/terms.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="terminos-del-servicio" tabindex="-1">Términos del servicio <a class="header-anchor" href="#terminos-del-servicio" aria-label="Permalink to “Términos del servicio”">​</a></h1><p>Estos Términos regulan el uso de la aplicación Sudoku. Al descargar, instalar o usar Sudoku, aceptas estos Términos. Si no estás de acuerdo, no utilices la aplicación.</p><h2 id="licencia-y-uso" tabindex="-1">Licencia y uso <a class="header-anchor" href="#licencia-y-uso" aria-label="Permalink to “Licencia y uso”">​</a></h2><p>Sudoku se distribuye bajo los términos de licencia incluidos con cada versión. Se te concede una licencia limitada, no exclusiva e intransferible para usar la aplicación en tus dispositivos de conformidad con los términos de la licencia.</p><h2 id="diseno-sin-conexion-con-funciones-en-la-nube-opcionales" tabindex="-1">Diseño sin conexión con funciones en la nube opcionales <a class="header-anchor" href="#diseno-sin-conexion-con-funciones-en-la-nube-opcionales" aria-label="Permalink to “Diseño sin conexión con funciones en la nube opcionales”">​</a></h2><p>Sudoku es una aplicación que funciona sin conexión en primer lugar. Todos los datos de juego (ajustes, estado de la partida y estadísticas) se almacenan localmente en tu dispositivo de forma predeterminada.</p><p>Las funciones en la nube opcionales incluyen:</p><ul><li><strong>Sincronización con iCloud</strong> (mediante CloudKit): sincroniza los datos entre tus dispositivos Apple usando tu cuenta personal de iCloud.</li><li><strong>Game Center</strong>: ofrece clasificaciones y logros.</li><li><strong>«Más apps»</strong>: función opcional que obtiene una lista de apps hermanas; no se transmite ningún dato personal.</li></ul><p>No recopilamos datos personales más allá de los que gestionan los servicios iCloud y Game Center de Apple cuando das tu consentimiento explícito.</p><h2 id="responsabilidades-del-usuario" tabindex="-1">Responsabilidades del usuario <a class="header-anchor" href="#responsabilidades-del-usuario" aria-label="Permalink to “Responsabilidades del usuario”">​</a></h2><ul><li>Usa Sudoku de forma lícita y conforme a las normas aplicables.</li><li>No intentes descompilar, aplicar ingeniería inversa ni modificar la app infringiendo la licencia.</li><li>No utilices la app con fines ilícitos.</li></ul><h2 id="privacidad" tabindex="-1">Privacidad <a class="header-anchor" href="#privacidad" aria-label="Permalink to “Privacidad”">​</a></h2><p>Consulta la Política de privacidad para obtener información sobre las prácticas en materia de datos. En resumen: no recopilamos ningún dato; las funciones en la nube opcionales utilizan únicamente los servicios iCloud y Game Center de Apple con tu consentimiento explícito.</p><h2 id="sin-garantias" tabindex="-1">Sin garantías <a class="header-anchor" href="#sin-garantias" aria-label="Permalink to “Sin garantías”">​</a></h2><p>Sudoku se proporciona «tal cual», sin garantías de ningún tipo. En la máxima medida permitida por la ley, los mantenedores renuncian a todas las garantías, tanto expresas como implícitas, legales o de otro tipo, incluidas las de comerciabilidad e idoneidad para un fin concreto.</p><h2 id="limitacion-de-responsabilidad" tabindex="-1">Limitación de responsabilidad <a class="header-anchor" href="#limitacion-de-responsabilidad" aria-label="Permalink to “Limitación de responsabilidad”">​</a></h2><p>En la máxima medida permitida por la ley, los mantenedores no se hacen responsables de los daños indirectos, incidentales, especiales, consecuentes o ejemplares que se deriven del uso de la aplicación.</p><h2 id="terminacion" tabindex="-1">Terminación <a class="header-anchor" href="#terminacion" aria-label="Permalink to “Terminación”">​</a></h2><p>Los derechos que se te conceden finalizan automáticamente si no cumples estos Términos.</p><h2 id="cambios" tabindex="-1">Cambios <a class="header-anchor" href="#cambios" aria-label="Permalink to “Cambios”">​</a></h2><p>Podemos actualizar estos Términos periódicamente. El uso continuado tras los cambios implica la aceptación de los Términos revisados.</p><h2 id="contacto" tabindex="-1">Contacto <a class="header-anchor" href="#contacto" aria-label="Permalink to “Contacto”">​</a></h2><p>Si tienes preguntas sobre estos Términos, abre un issue en el repositorio del proyecto: <code>https://github.com/sudoku-pro/sudoku-site/issues</code>.</p><p><em>Última actualización: 2026-07-29</em></p>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};